// No stdlib identity: the { it } lambda fills any (T) -> T slot
val lists = listOf(listOf("a", "b"), listOf("c"))
val flat = lists.flatMap { it }            // pass-through step in a pipeline

// The reusable form: one generic fun (a generic val is not possible)
fun <T> identity(x: T): T = x
val same = listOf("ana", "bob").map(::identity)

// Inside an inline HOF the pass-through costs no Function object
inline fun <T> applyOrPass(x: T, f: ((T) -> T)?): T = f?.invoke(x) ?: x
